package com.grocery.controller; import com.grocery.entity.*; import com.grocery.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/orders") public class OrderController{ private final GroceryOrderRepository r; public OrderController(GroceryOrderRepository r){this.r=r;} @GetMapping public List<GroceryOrder> all(){return r.findAll();} @PostMapping public GroceryOrder save(@RequestBody GroceryOrder o){return r.save(o);} @GetMapping("/{id}") public GroceryOrder one(@PathVariable Long id){return r.findById(id).orElseThrow();} @PutMapping("/{id}") public GroceryOrder update(@PathVariable Long id,@RequestBody GroceryOrder o){o.setId(id); return r.save(o);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){r.deleteById(id);} }